(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.UnitCircleLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function decimal(n,digits=4){return n.toFixed(digits).replace('.','{,}');}
function piTex(deg){const q=num.rational(deg,180);if(q.n===0)return '0';const top=Math.abs(q.n)===1?'\\pi':Math.abs(q.n)+'\\pi';return(q.n<0?'-':'')+(q.d===1?top:`\\frac{${top}}{${q.d}}`);}
function draw(){const deg=Number($('#unit-angle').value),c=core.coordinates(deg),p=core.point(c.cos,c.sin),x=p.x,y=p.y;$('#unit-angle-output').value=deg+'°';$('#cos-component').setAttribute('x2',x);for(const [key,value] of Object.entries({x1:x,x2:x,y1:180,y2:y}))$('#sin-component').setAttribute(key,value);$('#unit-ray').setAttribute('x2',x);$('#unit-ray').setAttribute('y2',y);$('#unit-point').setAttribute('cx',x);$('#unit-point').setAttribute('cy',y);const sx=Math.sign(c.cos),sy=Math.sign(c.sin);$('#right-angle').setAttribute('d',sx&&sy?`M${x-sx*10} 180L${x-sx*10} ${180-sy*10}L${x} ${180-sy*10}`:'');$('#unit-angle-arc').setAttribute('d',core.arc(deg).map((q,i)=>`${i===0?'M':'L'}${q.x} ${q.y}`).join(' '));math($('#unit-angle-equation'),`\\theta=${deg}^\\circ=${piTex(deg)}\\text{ rad}`);math($('#cos-value'),`\\cos\\theta${c.cosTex===null?'\\approx':'='}${c.cosTex===null?decimal(c.cos):c.cosTex}`);math($('#sin-value'),`\\sin\\theta${c.sinTex===null?'\\approx':'='}${c.sinTex===null?decimal(c.sin):c.sinTex}`);math($('#unit-pair'),`P=(\\cos\\theta,\\sin\\theta)\\approx(${decimal(c.cos)},${decimal(c.sin)})`);const place=c.cos===0||c.sin===0?'Titik berada pada sumbu, bukan di dalam suatu kuadran.':`Titik berada di kuadran ${c.cos>0?(c.sin>0?'I':'IV'):(c.sin>0?'II':'III')}.`;$('#unit-feedback').textContent=place+' '+(c.cosTex===null?'Nilai sudut ini ditampilkan sebagai pendekatan empat angka desimal.':'Kartu menampilkan nilai tepat; pasangan desimal adalah pendekatan empat angka desimal.')+' Koordinat bertanda menunjukkan arah. Panjang sisi segitiga, bila dipakai, adalah besar koordinat tanpa tanda.';$('#unit-plot').setAttribute('aria-label',`Lingkaran satuan pada sudut ${deg} derajat. Koordinat mendatar atau kosinus sekitar ${c.cos.toFixed(4)}; koordinat tegak atau sinus sekitar ${c.sin.toFixed(4)}. ${place}`);}
$('#unit-angle').addEventListener('input',draw);document.querySelectorAll('[data-angle]').forEach(button=>button.addEventListener('click',()=>{$('#unit-angle').value=button.dataset.angle;draw();}));$('#reset-unit').addEventListener('click',()=>{$('#unit-angle').value=60;draw();});draw();
$('#special-angle-table').innerHTML=[0,30,45,60,90].map(deg=>{const c=core.coordinates(deg);return `<tr><th scope="row"><span data-tex="${deg}^\\circ"></span></th><td><span data-tex="${piTex(deg)}"></span></td><td><span data-tex="${c.cosTex}"></span></td><td><span data-tex="${c.sinTex}"></span></td></tr>`;}).join('');
const questions=[{tex:'\\sin30^\\circ',prompt:'Berapa nilainya?',n:1,d:2,hint:'Pada sudut tiga puluh derajat, koordinat tegak pada lingkaran satuan adalah setengah.',why:'Sinus adalah koordinat tegak. Pada sudut tiga puluh derajat nilainya setengah.'},{tex:'\\cos180^\\circ',prompt:'Berapa nilainya?',n:-1,d:1,hint:'Setengah putaran berakhir pada titik paling kiri lingkaran satuan.',why:'Titik akhirnya memiliki koordinat mendatar negatif satu dan koordinat tegak nol. Kosinus membaca koordinat mendatar.'},{tex:'\\sin(-90^\\circ)',prompt:'Berapa nilainya?',n:-1,d:1,hint:'Seperempat putaran searah jarum jam berakhir pada titik paling bawah.',why:'Koordinat tegak titik itu negatif satu, sehingga sinusnya negatif satu.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis satu bilangan, misalnya 1/2 atau -1.':'Belum tepat. Periksa apakah yang dibaca koordinat mendatar atau tegak dan di mana titik akhirnya.');}));
const choices=[{tex:'\\theta=60^\\circ',prompt:'Apa pasangan koordinat titik pada lingkaran satuan?',options:[{tex:'(\\frac12,\\frac{\\sqrt3}{2})',label:'Setengah, lalu akar tiga dibagi dua'},{tex:'(\\frac{\\sqrt3}{2},\\frac12)',label:'Akar tiga dibagi dua, lalu setengah'},{tex:'(-\\frac12,\\frac{\\sqrt3}{2})',label:'Negatif setengah, lalu akar tiga dibagi dua'}],answer:0,why:'Urutannya kosinus dahulu, lalu sinus. Pada enam puluh derajat, kosinus setengah dan sinus akar tiga dibagi dua.'},{tex:'\\theta=225^\\circ',prompt:'Bagaimana tanda kosinus dan sinus sudut ini?',options:[{text:'Kosinus positif, sinus negatif.'},{text:'Keduanya negatif.'},{text:'Kosinus negatif, sinus positif.'}],answer:1,why:'Titik berada di kuadran III, yaitu kiri bawah. Kedua koordinatnya negatif.'},{tex:'\\cos^2\\theta+\\sin^2\\theta',prompt:'Berapa nilai jumlah ini untuk setiap sudut real?',options:[{text:'Nol.'},{text:'Bergantung kuadran.'},{text:'Satu.'}],answer:2,why:'Titik pada lingkaran satuan memenuhi kuadrat koordinat mendatar ditambah kuadrat koordinat tegak sama dengan satu.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}" ${o.label?'aria-label="'+o.label+'"':''}>${o.tex?'<span data-tex="'+o.tex+'"></span>':o.text}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-unit-circle-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-unit-circle-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();